import { Box, Container, Link, Stack, Typography } from "@mui/material";
import { mediaUrl } from "../services/api";
import type { HomeSubFooter } from "../types/home";
import appStoreBadge from "../assets/icons/appstore-apple.png";
import playStoreBadge from "../assets/icons/g-play.png";

const NAVY = "#17224d";
const APP_STORE_URL = "https://apps.apple.com/in/app/doctutorials-neet-pg-ss-fmge/id1475350376";
const PLAY_STORE_URL = "https://play.google.com/store/apps/details?id=in.dgist.doctutorials&hl=en_US";

export default function SubFooter({ data }: { data?: HomeSubFooter | null }) {
  if (!data) return null;

  const appStoreSrc = mediaUrl(data.appStoreImage) || appStoreBadge;
  const playStoreSrc = mediaUrl(data.playStoreImage) || playStoreBadge;

  return (
    <Box sx={{ py: { xs: 4, sm: 6, md: 8, tv: 10 }, backgroundColor: "#fff" }}>
      <Container
        maxWidth={false}
        sx={{ maxWidth: { xs: "100%", md: 1200, xl: 1360, tv: 1600 }, px: { xs: 2, sm: 3, md: 4, tv: 8 } }}
      >
        <Stack
          direction={{ xs: "column", lg: "row" }}
          alignItems={{ xs: "flex-start", lg: "center" }}
          spacing={{ xs: 4, sm: 5, md: 4, tv: 6 }}
          justifyContent="space-between"
        >
          <Box sx={{ flex: 1, width: "100%" }}>
            {data.coursesTitle ? (
              <Typography sx={{ color: NAVY, fontSize: { xs: 18, md: 22, tv: 26 }, fontWeight: 700, mb: 1.5 }}>
                {data.coursesTitle}
              </Typography>
            ) : null}
            <Box component="ul" sx={{ m: 0, pl: 2.5, mb: 3 }}>
              {(data.courses || []).map((item) => (
                <Box component="li" key={item.id || item.label} sx={{ mb: 0.75 }}>
                  <Link
                    href={item.url}
                    target={item.openInNewTab ? "_blank" : undefined}
                    rel={item.openInNewTab ? "noopener noreferrer" : undefined}
                    underline="hover"
                    sx={{ color: NAVY, fontSize: { xs: 14, md: 15, tv: 17 } }}
                  >
                    {item.label}
                  </Link>
                </Box>
              ))}
            </Box>
            {data.centersTitle ? (
              <Typography sx={{ color: NAVY, fontSize: { xs: 18, md: 22, tv: 26 }, fontWeight: 700, mb: 1.5 }}>
                {data.centersTitle}
              </Typography>
            ) : null}
            <Typography sx={{ color: NAVY, fontSize: { xs: 14, md: 15, tv: 17 } }}>
              {(data.centers || []).map((item, index) => (
                <Box component="span" key={item.id || item.label}>
                  {index > 0 ? " | " : null}
                  <Link
                    href={item.url}
                    target={item.openInNewTab ? "_blank" : undefined}
                    rel={item.openInNewTab ? "noopener noreferrer" : undefined}
                    underline="hover"
                    sx={{ color: NAVY }}
                  >
                    {item.label}
                  </Link>
                </Box>
              ))}
            </Typography>
          </Box>

          {mediaUrl(data.centerImage) ? (
            <Box sx={{ flex: 1, width: "100%", textAlign: "center" }}>
              <Box
                component="img"
                src={mediaUrl(data.centerImage)}
                alt=""
                sx={{ width: "100%", maxWidth: { xs: 280, sm: 360, md: 450, tv: 540 }, display: "block", mx: { xs: 0, lg: "auto" } }}
              />
            </Box>
          ) : null}

          <Box sx={{ flex: 1, width: "100%", textAlign: { xs: "left", sm: "center" } }}>
            {data.qrTitle ? (
              <Typography sx={{ color: NAVY, fontSize: { xs: 18, md: 22, tv: 26 }, fontWeight: 700, mb: 2 }}>
                {data.qrTitle}
              </Typography>
            ) : null}
            {mediaUrl(data.qrImage) ? (
              <Box
                component="img"
                src={mediaUrl(data.qrImage)}
                alt="QR"
                sx={{ width: { xs: 120, md: 142, tv: 168 }, display: "block", mx: { xs: 0, sm: "auto" }, mb: 1.5 }}
              />
            ) : null}
            <Typography sx={{ color: NAVY, fontSize: { xs: 14, md: 16, tv: 18 }, mb: 2 }}>{data.qrOrText || "OR"}</Typography>
            <Stack direction="row" justifyContent={{ xs: "flex-start", sm: "center" }} spacing={1.5} flexWrap="wrap" useFlexGap>
              <Box
                component="a"
                href={data.appStoreUrl || APP_STORE_URL}
                target="_blank"
                rel="noopener noreferrer"
              >
                <Box component="img" src={appStoreSrc} alt="App Store" sx={{ height: { xs: 34, md: 40, tv: 48 } }} />
              </Box>
              <Box
                component="a"
                href={data.playStoreUrl || PLAY_STORE_URL}
                target="_blank"
                rel="noopener noreferrer"
              >
                <Box component="img" src={playStoreSrc} alt="Play Store" sx={{ height: 40 }} />
              </Box>
            </Stack>
          </Box>
        </Stack>
      </Container>
    </Box>
  );
}
